// GENERATED by `npm run build` from hooks/*/hooks.json — do not edit; change the
// source and rebuild (see AGENTS.md). Drift is a CI failure.
//
// OpenCode plugin for the "astra" plugin, version 0.0.5 — installed from npm as
// @lightcone-research/astra-plugin. Runs the very same hook scripts the Claude Code and Codex packages of
// this plugin run (embedded below, tool versions already pinned) and routes their
// output the harness's way. Needs `bash` on PATH; the scripts need `uvx` and say
// so themselves when it is missing. Nothing else.
//
//   PostToolUse  → "tool.execute.after": additionalContext is appended to the
//                  tool result the model reads.
//   SessionStart → "experimental.chat.system.transform": the primer runs once
//                  per session (pre-warmed on the session.created event) and is
//                  appended to the system prompt on every request.

import { spawn } from "node:child_process";

function matches(matcher, tool) {
  if (!matcher) return true;
  return new RegExp("^(?:" + matcher + ")$", "i").test(tool || "");
}

// Run one embedded script with the payload on stdin (what the harness would
// have piped), in the project directory, killed after its hooks.json timeout.
// Resolves to whatever it printed — never rejects: a hook must not break the
// tool call or the request it decorates. No bash on PATH → silent.
function runScript(name, payload, cwd, timeoutSeconds) {
  return new Promise((resolve) => {
    let out = "";
    let child;
    try {
      child = spawn("bash", ["-c", SCRIPTS[name]], { cwd, env: process.env, stdio: ["pipe", "pipe", "ignore"] });
    } catch {
      return resolve("");
    }
    const timer = setTimeout(() => child.kill(), timeoutSeconds * 1000);
    child.stdout.on("data", (chunk) => (out += chunk));
    child.on("error", () => { clearTimeout(timer); resolve(out); });
    child.on("close", () => { clearTimeout(timer); resolve(out); });
    child.stdin.on("error", () => {});
    child.stdin.end(payload);
  });
}

// Each script prints hook envelopes, one JSON object per line; collect their
// additionalContext and drop anything that is not an envelope.
function contextOf(stdout) {
  const parts = [];
  for (const line of stdout.split("\n")) {
    if (!line.trim()) continue;
    try {
      const ctx = JSON.parse(line)?.hookSpecificOutput?.additionalContext;
      if (typeof ctx === "string" && ctx.trim()) parts.push(ctx.trim());
    } catch {}
  }
  return parts.join("\n\n");
}

async function runGroups(groups, tool, payload, cwd) {
  const parts = [];
  for (const group of groups) {
    if (!matches(group.matcher, tool)) continue;
    for (const script of group.scripts) {
      const ctx = contextOf(await runScript(script.name, payload, cwd, script.timeout));
      if (ctx) parts.push(ctx);
    }
  }
  return parts.join("\n\n");
}

// The payload mirrors the Claude Code hook JSON the scripts were written for.
function hookPayload(event, cwd, extra) {
  return JSON.stringify(Object.assign({ hook_event_name: event, cwd: cwd, plugin: PLUGIN }, extra));
}

const PLUGIN = "astra";

// The hook scripts, byte-identical to plugins/astra/hooks/scripts/*.sh.
const SCRIPTS = {
  "astra-session-start.sh": "#!/bin/bash\n# SessionStart hook (astra plugin): orient the agent in an ASTRA project.\n#\n# Everything here is dynamic — read from the environment at session start:\n# where the spec lives, and the analysis's shape from `astra info`. The one\n# static line is the skill pointer.\n#\n# Self-contained on purpose — no sourcing, no jq/sed/awk. The astra-tools\n# version in the uvx invocation comes from the bundling plugin's `tools` pin\n# in skills.config.json: canonical sources write the @x.y.z placeholder and\n# `npm run build` substitutes the pin into the packaged copies. The --json\n# mode emits the header as ONE JSON-encoded, ANSI-free string, spliced into a\n# printf template; the only string surgery is stripping the outer quotes.\n#\n# Deliberately NOT here:\n#   - execution-layer status -- this plugin is about the ASTRA spec.\n#   - astra validate -- validation is an opinion about the work, not\n#     session state; it belongs to validate-on-save, which fires at the\n#     moment an ASTRA file actually changes.\n#   - skill listing -- the harness already advertises installed skills.\n#\n#   SessionStart ──▶ ./astra.yaml present? ──no──▶ exit silent\n#                          │yes\n#                          ▼\n#                     uvx present? ──no──▶ inject \"install uv to enable astra\"\n#                          │yes\n#                          ▼\n#                     astra info --json ──ok──▶ inject spec path + info\n#                          │not a JSON string\n#                          ▼\n#                     inject \"toolchain problem or malformed spec\"\n\ncat >/dev/null # consume the payload; everything needed comes from the cwd\n[ -f astra.yaml ] || exit 0\n\nif ! command -v uvx &>/dev/null; then\n    printf '{\"hookSpecificOutput\":{\"hookEventName\":\"SessionStart\",\"additionalContext\":\"ASTRA project — spec at ./astra.yaml\\\\n`uv` is not installed, so the astra CLI is unavailable. Ask the user if they would like to install it (https://docs.astral.sh/uv/getting-started/installation/).\\\\n\\\\nActivate the astra skill when working with ASTRA analyses.\\\\n\"}}\\n'\n    exit 0\nfi\n\nheader=$(uvx astra-tools@0.2.17 info --json 2>/dev/null)\nrc=$?\n\ncase \"$rc:$header\" in\n    0:\\\"*\\\")\n        body=\"${header#\\\"}\"\n        body=\"${body%\\\"}\"\n        printf '{\"hookSpecificOutput\":{\"hookEventName\":\"SessionStart\",\"additionalContext\":\"ASTRA project — spec at ./astra.yaml\\\\n%s\\\\nActivate the astra skill when working with ASTRA analyses.\\\\n\"}}\\n' \\\n            \"$body\"\n        ;;\n    *)\n        printf '{\"hookSpecificOutput\":{\"hookEventName\":\"SessionStart\",\"additionalContext\":\"ASTRA project — spec at ./astra.yaml\\\\nCould not run `astra info` (exit %s) — a toolchain problem, or a malformed spec; run `astra validate astra.yaml` to see which.\\\\n\\\\nActivate the astra skill when working with ASTRA analyses.\\\\n\"}}\\n' \\\n            \"$rc\"\n        ;;\nesac\nexit 0\n",
  "validate-on-save.sh": "#!/bin/bash\n# PostToolUse(Write|Edit|apply_patch) hook: when a save plausibly touched the\n# ASTRA spec, re-validate ./astra.yaml and push the result back to the agent\n# as additionalContext.\n#\n# Self-contained on purpose — no sourcing, no jq/sed/awk. The astra-tools\n# version in the uvx invocation comes from the bundling plugin's `tools` pin\n# in skills.config.json: canonical sources write the @x.y.z placeholder and\n# `npm run build` substitutes the pin into the packaged copies.\n#   - trigger: a bash substring match on the raw payload (\"astra.yaml\"\n#     mentioned anywhere). It can over-trigger, which costs one harmless\n#     validation run; the [ -f ] gate keeps non-ASTRA sessions silent.\n#   - target: always ./astra.yaml in the session directory (universe files\n#     are not validated at hook level — the spec is what the agent authors).\n#   - JSON: `astra validate --json` emits its report as ONE JSON-encoded,\n#     ANSI-free string, so the response is assembled by splicing that string\n#     into a printf template; the only string surgery is stripping the outer\n#     quotes.\n#\n#   Write/Edit/apply_patch ──▶ payload mentions astra.yaml? ──no──▶ exit silent\n#                     │yes\n#                     ▼\n#                ./astra.yaml exists? ──no──▶ exit silent\n#                     │yes\n#                     ▼\n#                uvx present? ──no──▶ inject \"saved but NOT validated; ask user to install uv\"\n#                     │yes\n#                     ▼\n#                astra validate astra.yaml --json ──pass──▶ inject \"validation passed\"\n#                     │fail                       │not a JSON string\n#                     ▼                           ▼\n#                inject verbatim report      inject \"toolchain problem\"\n\ninput=$(cat)\n\ncase \"$input\" in\n    *astra.yaml*) ;;\n    *) exit 0 ;;\nesac\n\n[ -f astra.yaml ] || exit 0\n\n# If uv is not present, ask the USER to install it rather than failing\n# silently. Never install uv from here.\nif ! command -v uvx &>/dev/null; then\n    printf '{\"hookSpecificOutput\":{\"hookEventName\":\"PostToolUse\",\"additionalContext\":\"ASTRA file saved but not validated: `uv` is not installed. Ask the user if they would like to install it (https://docs.astral.sh/uv/getting-started/installation/) to enable validation.\\\\n\"}}\\n'\n    exit 0\nfi\n\nreport=$(uvx astra-tools@0.2.17 validate astra.yaml --json 2>/dev/null)\nrc=$?\n\ncase \"$report\" in\n    \\\"*\\\")\n        body=\"${report#\\\"}\"\n        body=\"${body%\\\"}\"\n        if [ \"$rc\" -eq 0 ]; then\n            printf '{\"hookSpecificOutput\":{\"hookEventName\":\"PostToolUse\",\"additionalContext\":\"ASTRA validation passed for ./astra.yaml\\\\n\"}}\\n'\n        else\n            printf '{\"hookSpecificOutput\":{\"hookEventName\":\"PostToolUse\",\"additionalContext\":\"ASTRA validation FAILED for ./astra.yaml:\\\\n%s\"}}\\n' \\\n                \"$body\"\n        fi\n        ;;\n    *)\n        # astra produced no JSON string — uvx resolution, network, or a crash.\n        printf '{\"hookSpecificOutput\":{\"hookEventName\":\"PostToolUse\",\"additionalContext\":\"ASTRA file saved but not validated: the pinned astra toolchain failed to run (exit %s) — a toolchain problem, not a statement about the spec.\\\\n\"}}\\n' \\\n            \"$rc\"\n        ;;\nesac\nexit 0\n",
};

// Wiring lifted from hooks.json. Matchers are the Claude/Codex tool-name
// regexes; harness tool ids are lowercase, so matching is case-insensitive.
const POST_TOOL_USE = [
  {
    "matcher": "Write|Edit|apply_patch",
    "scripts": [
      {
        "name": "validate-on-save.sh",
        "timeout": 90
      }
    ]
  }
];
const SESSION_START = [
  {
    "matcher": "",
    "scripts": [
      {
        "name": "astra-session-start.sh",
        "timeout": 90
      }
    ]
  }
];

/** @type {import("@opencode-ai/plugin").Plugin} */
export default async function ({ directory }) {
  const cwd = directory || process.cwd();
  const primers = new Map(); // sessionID → Promise<string>; one SessionStart per session
  const primer = (sessionID) => {
    const key = sessionID ?? "";
    if (!primers.has(key)) {
      const payload = hookPayload("SessionStart", cwd, { session_id: key, source: "startup" });
      primers.set(key, runGroups(SESSION_START, "", payload, cwd));
    }
    return primers.get(key);
  };

  const hooks = {};
  hooks.event = async ({ event }) => {
    if (event?.type === "session.created") void primer(event.properties?.info?.id);
  };
  hooks["experimental.chat.system.transform"] = async (input, output) => {
    const ctx = await primer(input?.sessionID);
    if (ctx) output.system.push(ctx);
  };
  hooks["tool.execute.after"] = async (input, output) => {
    const payload = hookPayload("PostToolUse", cwd, {
      session_id: input.sessionID,
      tool_name: input.tool,
      tool_input: input.args,
      tool_response: { title: output?.title },
    });
    const ctx = await runGroups(POST_TOOL_USE, input.tool, payload, cwd);
    if (ctx) output.output = (output.output ?? "") + "\n\n" + ctx;
  };
  return hooks;
}
